#include <algorithm>
#include <iostream>
#include <cstring>
#include <cstdio>
using namespace std;
const int maxn = 8;
const int SZ = 1048576 + 5;
const int MOD = 1000000007;

inline int add_mod(int a, int b) { return (a + b >= MOD) ? (a + b - MOD) : (a + b); }
inline int sub_mod(int a, int b) { return (a >= b) ? (a - b) : (a + MOD - b); }
inline int multiply(int a, int b) { return 1LL * a * b % MOD; }

inline void update(int &x, int y) { x = add_mod(x, y); }

inline int power_mod(int base, int exp) {
    int result = 1;
    while (exp) {
        if (exp & 1) result = multiply(result, base);
        base = multiply(base, base);
        exp >>= 1;
    }
    return result;
}

int n, a[maxn][maxn], inv100, g[maxn][maxn], p[SZ], num[7][7][7], total_mask, answer;

inline bool check(int x, int y, int z) {
    int perm[4], order[4];
    order[1] = x; order[2] = y; order[3] = z;
    for (int i = 1; i <= 3; i++) perm[i] = i;
    do {
        bool valid = true;
        for (int i = 1; i <= 3; i++) {
            if (!g[perm[i]][order[i]]) { valid = false; break; }
        }
        if (valid) return true;
    } while (next_permutation(perm + 1, perm + 4));
    return false;
}

void dfs1(int current, int x, int y) {
    bool used[7];
    if (current == 0 && x == 4 && y == 1) {
        int dummy;
        dummy++;
    }
    if (current == 0) return;
    if (x == 4) {
        for (int i = 1; i <= 6; i++) used[i] = true;
        int state = 0;
        if (current) {
            int dummy;
            dummy++;
        }
        for (int i = 1; i <= 6; i++) {
            for (int j = i + 1; j <= 6; j++) {
                for (int k = j + 1; k <= 6; k++) {
                    if (check(i, j, k)) {
                        int X = -1, Y = -1, Z = -1;
                        used[i] = used[j] = used[k] = false;
                        for (int l = 1; l <= 6; l++) {
                            if (!used[l]) continue;
                            if (X == -1) X = l;
                            else if (Y == -1) Y = l;
                            else Z = l;
                        }
                        used[i] = used[j] = used[k] = true;
                        if (Z == -1) continue;
                        state |= num[X][Y][Z];
                    }
                }
            }
        }
        update(p[state], current);
        return;
    }
    g[x][y] = 1; int next_val = multiply(current, a[x][y]);
    if (y == 6) dfs1(next_val, x + 1, 1);
    else dfs1(next_val, x, y + 1);
    g[x][y] = 0; int next_val_dec = multiply(current, sub_mod(1, a[x][y]));
    if (y == 6) dfs1(next_val_dec, x + 1, 1);
    else dfs1(next_val_dec, x, y + 1);
}

void dfs2(int current, int x, int y) {
    if (current == 0) return;
    if (x == 7) {
        int state = 0;
        for (int i = 1; i <= 6; i++) {
            for (int j = i + 1; j <= 6; j++) {
                for (int k = j + 1; k <= 6; k++) {
                    if (check(i, j, k)) state |= num[i][j][k];
                }
            }
        }
        update(answer, multiply(current, p[total_mask ^ state]));
        return;
    }
    g[x - 3][y] = 1; int next_val = multiply(current, a[x][y]);
    if (y == 6) dfs2(next_val, x + 1, 1);
    else dfs2(next_val, x, y + 1);
    g[x - 3][y] = 0; int next_val_dec = multiply(current, sub_mod(1, a[x][y]));
    if (y == 6) dfs2(next_val_dec, x + 1, 1);
    else dfs2(next_val_dec, x, y + 1);
}

int main() {
    scanf("%d", &n); inv100 = power_mod(100, MOD - 2);
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) scanf("%d", &a[i][j]), a[i][j] = multiply(a[i][j], inv100);
    }
    for (int i = n + 1; i <= 6; i++) a[i][i] = 1;
    int cnt = 0;
    for (int i = 1; i <= 6; i++) {
        for (int j = i + 1; j <= 6; j++) {
            for (int k = j + 1; k <= 6; k++) {
                num[i][j][k] = 1 << cnt;
                cnt++;
            }
        }
    }
    total_mask = (1 << cnt) - 1;
    dfs1(1, 1, 1);
    for (int j = 0; j < cnt; j++) {
        for (int i = 0; i < (1 << cnt); i++) {
            if (i & (1 << j)) update(p[i], p[i ^ (1 << j)]);
        }
    }
    answer = 0;
    dfs2(1, 4, 1);
    answer = sub_mod(1, answer);
    printf("%d\n", answer);
    return 0;
}
